<div class="card" style="max-width:700px;margin:0 auto;"><div class="card-header"><h1>Profit Margin Calculator</h1><p>Calculate profit margin instantly.</p></div><?php if($generalErr):?><div class="alert alert-error"><?php echo e($generalErr);?></div><?php endif;?><?php if($successMsg):?><div class="alert alert-success"><?php echo e($successMsg);?></div><?php endif;?>
<form method="post" action="<?php echo e(url_for('seller','margin'));?>"><?php echo csrf_field();?><input type="hidden" name="action" value="add"><div class="field"><label>Product Name</label><input type="text" name="name"></div><div class="col-half"><div class="field"><label>Cost Price (TK)</label><input type="number" step="0.01" min="0" id="cost_price" name="cost_price"></div></div><div class="col-half"><div class="field"><label>Selling Price (TK)</label><input type="number" step="0.01" min="0" id="selling_price" name="selling_price"></div></div><div class="clear"></div><div class="alert alert-info" style="text-align:center;">Margin: <strong id="marginOut">—</strong> <span class="small muted" id="marginHint">(enter both prices)</span></div><div class="field"><label>Stock Qty</label><input type="number" min="0" name="stock_qty" value="10"></div><div class="field"><label>Description</label><textarea name="description" rows="2"></textarea></div><button class="btn btn-primary btn-block">Add Product</button></form></div>
<div class="card"><div class="card-header"><h2>Your Products</h2></div><?php if(!$products):?><p class="muted">No products yet.</p><?php else:?><table class="data-table"><tr><th>ID</th><th>Name</th><th>Cost → Sell</th><th>Margin</th><th>Stock</th><th>Action</th></tr><?php foreach($products as $p):?><tr><td>#<?php echo e($p['id']);?></td><td><?php echo e($p['name']);?></td><td>TK <?php echo e(number_format((float)$p['cost_price'],2));?> → TK <?php echo e(number_format((float)$p['selling_price'],2));?></td><td><?php echo e(number_format((float)$p['profit_margin'],2));?>%</td><td><?php echo e($p['stock_qty']);?></td><td><form method="post" action="<?php echo e(url_for('seller','margin'));?>"><?php echo csrf_field();?><input type="hidden" name="action" value="delete"><input type="hidden" name="product_id" value="<?php echo e($p['id']);?>"><button class="btn btn-secondary btn-small" data-confirm="Delete product #<?php echo e($p['id']);?>?">Delete</button></form></td></tr><?php endforeach;?></table><?php endif;?></div>
